write("backend/src/store.js", textwrap.dedent("""\
const fs = require("fs");
const path = require("path");

function ensureDir(filePath) {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

/**
 * Tiny JSON store to persist coupon usage.
 * Stored at STORE_PATH (default: /data/store.json) and backed by a Docker volume.
 */
class JsonStore {
  constructor(filePath) {
    this.filePath = filePath;
    ensureDir(this.filePath);
    this._lock = Promise.resolve();

    if (!fs.existsSync(this.filePath)) {
      fs.writeFileSync(this.filePath, JSON.stringify({ coupon_usage: {} }, null, 2));
    }

    this.data = this._readSync();
    if (!this.data.coupon_usage) this.data.coupon_usage = {};
  }

  _readSync() {
    try {
      const raw = fs.readFileSync(this.filePath, "utf-8");
      return JSON.parse(raw);
    } catch (e) {
      return { coupon_usage: {} };
    }
  }

  _writeSync() {
    fs.writeFileSync(this.filePath, JSON.stringify(this.data, null, 2));
  }

  /**
   * Simple mutex to serialize writes.
   */
  async withLock(fn) {
    const run = async () => fn();
    this._lock = this._lock.then(run, run);
    return this._lock;
  }

  getUsageCount(userId, couponCode) {
    const u = String(userId || "").trim();
    const c = String(couponCode || "").trim().toUpperCase();
    if (!u || !c) return 0;
    return (this.data.coupon_usage?.[u]?.[c]) || 0;
  }

  incrementUsage(userId, couponCode) {
    const u = String(userId || "").trim();
    const c = String(couponCode || "").trim().toUpperCase();
    if (!u || !c) return;

    if (!this.data.coupon_usage[u]) this.data.coupon_usage[u] = {};
    this.data.coupon_usage[u][c] = (this.data.coupon_usage[u][c] || 0) + 1;
    this._writeSync();
  }
}

module.exports = { JsonStore };
"""))

