write("backend/src/pricing.js", textwrap.dedent("""\
const { COUPONS, isExpired } = require("./coupons");
const { findProduct } = require("./products");

/**
 * 10% automatic discount is applied first.
 * Then coupon discount is applied.
 * Totals are clamped to >= 0.
 */
function calcQuote({ userId, items, couponCode }, store, { consumeOneTimeCoupon } = { consumeOneTimeCoupon: false }) {
  const errors = [];
  const messages = [];

  const normalizedUserId = String(userId || "").trim();
  if (!normalizedUserId) errors.push("Please enter a User ID.");

  const normalizedItems = Array.isArray(items) ? items : [];
  if (normalizedItems.length === 0) errors.push("Cart is empty.");

  // Build subtotal from server-side catalog (ignore client prices)
  let subtotal = 0;
  const lineItems = [];

  for (const it of normalizedItems) {
    const productId = String(it.productId || "").trim();
    const qty = Number(it.qty);
    if (!productId) { errors.push("Invalid productId."); continue; }
    if (!Number.isInteger(qty) || qty <= 0) { errors.push(`Invalid quantity for product ${productId}.`); continue; }

    const product = findProduct(productId);
    if (!product) { errors.push(`Unknown product: ${productId}.`); continue; }

    const lineTotal = product.price_satang * qty;
    subtotal += lineTotal;
    lineItems.push({
      productId: product.id,
      name: product.name,
      price_satang: product.price_satang,
      qty,
      line_total_satang: lineTotal
    });
  }

  // Automatic 10% off (rounded to nearest satang)
  const auto_discount = Math.round(subtotal * 10 / 100);
  const subtotal_after_auto = Math.max(0, subtotal - auto_discount);

  let coupon_discount = 0;
  let appliedCoupon = null;

  const code = String(couponCode || "").trim().toUpperCase();
  if (code) {
    const coupon = COUPONS[code];
    if (!coupon) {
      errors.push("Invalid coupon code.");
    } else if (isExpired(coupon)) {
      errors.push("Coupon expired.");
    } else if (subtotal < (coupon.min_subtotal_satang || 0)) {
      // requirement based on subtotal BEFORE discounts
      const min = coupon.min_subtotal_satang || 0;
      errors.push(`Minimum purchase not met. Need at least ${formatBaht(min)} baht.`);
    } else if (coupon.per_user_limit) {
      const used = store.getUsageCount(normalizedUserId, code);
      if (used >= coupon.per_user_limit) {
        errors.push("You already used this.");
      } else {
        // valid
        appliedCoupon = coupon;
      }
    } else {
      appliedCoupon = coupon;
    }

    if (appliedCoupon) {
      // fixed coupon
      coupon_discount = Math.min(appliedCoupon.amount_satang, subtotal_after_auto);
      if (coupon_discount > 0) messages.push("Success");
    }
  }

  const total = Math.max(0, subtotal_after_auto - coupon_discount);

  // Consume one-time coupon only on confirm, not quote
  if (consumeOneTimeCoupon && appliedCoupon && appliedCoupon.per_user_limit && coupon_discount > 0) {
    store.incrementUsage(normalizedUserId, appliedCoupon.code);
  }

  return {
    ok: errors.length === 0,
    errors,
    messages,
    userId: normalizedUserId,
    items: lineItems,
    couponCode: code || null,
    appliedCoupon: appliedCoupon ? {
      code: appliedCoupon.code,
      amount_satang: appliedCoupon.amount_satang,
      min_subtotal_satang: appliedCoupon.min_subtotal_satang || 0,
      expires_at: appliedCoupon.expires_at,
      per_user_limit: appliedCoupon.per_user_limit
    } : null,
    pricing: {
      subtotal_satang: subtotal,
      auto_discount_satang: auto_discount,
      subtotal_after_auto_satang: subtotal_after_auto,
      coupon_discount_satang: coupon_discount,
      total_satang: total
    }
  };
}

function formatBaht(satang) {
  return (satang / 100).toFixed(2);
}

module.exports = { calcQuote, formatBaht };
"""))

write("backend/src/server.js", textwrap.dedent("""\
const express = require("express");
const cors = require("cors");
const { JsonStore } = require("./store");
const { PRODUCTS } = require("./products");
const { calcQuote } = require("./pricing");

const app = express();
app.use(cors());
app.use(express.json({ limit: "200kb" }));

const PORT = process.env.PORT || 4000;
const STORE_PATH = process.env.STORE_PATH || "/data/store.json";
const store = new JsonStore(STORE_PATH);

app.get("/api/health", (req, res) => {
  res.json({ ok: true, service: "promo-backend" });
});

app.get("/api/products", (req, res) => {
  res.json({ products: PRODUCTS });
});

app.post("/api/checkout/quote", async (req, res) => {
  // Quote does not consume one-time coupons
  const payload = req.body || {};
  const result = calcQuote(payload, store, { consumeOneTimeCoupon: false });
  res.status(result.ok ? 200 : 400).json(result);
});

app.post("/api/checkout/confirm", async (req, res) => {
  // Confirm consumes one-time coupons if applied
  const payload = req.body || {};

  const result = await store.withLock(() => {
    return calcQuote(payload, store, { consumeOneTimeCoupon: true });
  });

  res.status(result.ok ? 200 : 400).json(result);
});

app.listen(PORT, () => {
  console.log(`promo-backend listening on http://0.0.0.0:${PORT}`);
  console.log(`store path: ${STORE_PATH}`);
});
"""))

