import React, { useEffect, useMemo, useState } from "react";
import { CartItem, Product, QuoteResponse, confirm, formatBaht, getProducts, quote } from "./api";
import { loadCart, loadUserId, saveCart, saveUserId } from "./storage";

function clampQty(n: number) {
  if (!Number.isInteger(n)) return 1;
  return Math.max(1, Math.min(99, n));
}

export default function App() {
  const [products, setProducts] = useState<Product[]>([]);
  const [cart, setCart] = useState<CartItem[]>(loadCart());
  const [userId, setUserId] = useState(loadUserId());
  const [couponCode, setCouponCode] = useState<string>("SAVE100");
  const [quoteResult, setQuoteResult] = useState<QuoteResponse | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    getProducts().then(setProducts).catch(() => setProducts([]));
  }, []);

  useEffect(() => {
    saveCart(cart);
  }, [cart]);

  useEffect(() => {
    saveUserId(userId);
  }, [userId]);

  const productMap = useMemo(() => {
    const m = new Map<string, Product>();
    for (const p of products) m.set(p.id, p);
    return m;
  }, [products]);

  const localSubtotalSatang = useMemo(() => {
    let s = 0;
    for (const it of cart) {
      const p = productMap.get(it.productId);
      if (!p) continue;
      s += p.price_satang * it.qty;
    }
    return s;
  }, [cart, productMap]);

  function addToCart(productId: string) {
    setCart(prev => {
      const copy = [...prev];
      const i = copy.findIndex(x => x.productId === productId);
      if (i >= 0) copy[i] = { ...copy[i], qty: clampQty(copy[i].qty + 1) };
      else copy.push({ productId, qty: 1 });
      return copy;
    });
  }

  function updateQty(productId: string, qty: number) {
    setCart(prev => prev.map(x => x.productId === productId ? { ...x, qty: clampQty(qty) } : x));
  }

  function removeItem(productId: string) {
    setCart(prev => prev.filter(x => x.productId !== productId));
  }

  async function runQuote() {
    setLoading(true);
    try {
      const res = await quote({ userId, items: cart, couponCode: couponCode.trim() || undefined });
      setQuoteResult(res);
    } finally {
      setLoading(false);
    }
  }

  async function runConfirm() {
    setLoading(true);
    try {
      const res = await confirm({ userId, items: cart, couponCode: couponCode.trim() || undefined });
      setQuoteResult(res);
      if (res.ok) {
        // simulate purchase success: clear cart
        setCart([]);
        setCouponCode("");
      }
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    // auto quote on load
    if (products.length) runQuote();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [products.length]);

  return (
    <div className="container">
      <div className="row space" style={{ marginBottom: 16 }}>
        <div>
          <h1 className="h1">Promotion & Discount Demo Shop</h1>
          <p className="small m0">
            Auto discount: <span className="badge">10% off</span> applied first, then coupon.
          </p>
        </div>
        <div style={{ width: 240 }}>
          <label className="small">User ID (used for one-time coupon)</label>
          <input className="input" value={userId} onChange={(e) => setUserId(e.target.value)} placeholder="e.g. toy" />
          <div className="small" style={{ marginTop: 6 }}>
            Try: <span className="badge">WELCOME</span> only once per user.
          </div>
        </div>
      </div>

      <div className="grid grid-2">
        <div className="card">
          <h2 className="h2">Products</h2>
          <table className="table">
            <thead>
              <tr><th>Item</th><th>Price</th><th></th></tr>
            </thead>
            <tbody>
              {products.map(p => (
                <tr key={p.id}>
                  <td><strong>{p.name}</strong> <span className="badge">{p.id}</span></td>
                  <td>{formatBaht(p.price_satang)} baht</td>
                  <td><button className="btn" onClick={() => addToCart(p.id)}>Add</button></td>
                </tr>
              ))}
            </tbody>
          </table>
          <p className="small" style={{ marginTop: 12 }}>
            Coupons: <span className="badge">SAVE100</span> (min 500), <span className="badge">WELCOME</span> (one time), <span className="badge">EXPIRED10</span> (expired).
          </p>
        </div>

        <div className="card">
          <h2 className="h2">Cart & Checkout</h2>

          {cart.length === 0 ? (
            <p className="small">Cart is empty. Add something.</p>
          ) : (
            <table className="table">
              <thead>
                <tr><th>Item</th><th>Qty</th><th>Line</th><th></th></tr>
              </thead>
              <tbody>
                {cart.map(it => {
                  const p = productMap.get(it.productId);
                  if (!p) return null;
                  return (
                    <tr key={it.productId}>
                      <td>{p.name} <span className="badge">{p.id}</span></td>
                      <td style={{ width: 90 }}>
                        <input
                          className="input"
                          type="number"
                          min={1}
                          max={99}
                          value={it.qty}
                          onChange={(e) => updateQty(it.productId, parseInt(e.target.value || "1", 10))}
                        />
                      </td>
                      <td>{formatBaht(p.price_satang * it.qty)} baht</td>
                      <td><button className="btn btn-secondary" onClick={() => removeItem(it.productId)}>Remove</button></td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}

          <div style={{ marginTop: 12 }}>
            <label className="small">Coupon Code</label>
            <input className="input" value={couponCode} onChange={(e) => setCouponCode(e.target.value)} placeholder="e.g. SAVE100" />
          </div>

          <div className="row" style={{ marginTop: 12 }}>
            <button className="btn btn-secondary" onClick={runQuote} disabled={loading}>Update Total</button>
            <button className="btn" onClick={runConfirm} disabled={loading || cart.length === 0}>Pay Now</button>
          </div>

          <div style={{ marginTop: 12 }}>
            <div className="small">Local subtotal (client view): {formatBaht(localSubtotalSatang)} baht</div>
          </div>

          {quoteResult && (
            <div style={{ marginTop: 12 }}>
              {quoteResult.messages?.map((m, idx) => (
                <div key={idx} className="msg-ok" style={{ marginBottom: 8 }}>{m}</div>
              ))}
              {quoteResult.errors?.map((e, idx) => (
                <div key={idx} className="msg-err" style={{ marginBottom: 8 }}>{e}</div>
              ))}

              <div className="card" style={{ padding: 12 }}>
                <div className="row space"><div>Subtotal</div><strong>{formatBaht(quoteResult.pricing.subtotal_satang)} baht</strong></div>
                <div className="row space"><div>Automatic 10% discount</div><strong>- {formatBaht(quoteResult.pricing.auto_discount_satang)} baht</strong></div>
                <div className="row space"><div>After auto discount</div><strong>{formatBaht(quoteResult.pricing.subtotal_after_auto_satang)} baht</strong></div>
                <div className="row space"><div>Coupon discount</div><strong>- {formatBaht(quoteResult.pricing.coupon_discount_satang)} baht</strong></div>
                <hr style={{ border: "none", borderTop: "1px solid rgba(255,255,255,0.12)", margin: "10px 0" }} />
                <div className="row space"><div>Total</div><strong>{formatBaht(quoteResult.pricing.total_satang)} baht</strong></div>
                <div className="small" style={{ marginTop: 8 }}>
                  Order is always: <span className="badge">10% first</span> then <span className="badge">coupon</span>. Total never below 0.
                </div>
              </div>

              {quoteResult.appliedCoupon && (
                <div className="small" style={{ marginTop: 10 }}>
                  Applied coupon: <span className="badge">{quoteResult.appliedCoupon.code}</span> (expires {new Date(quoteResult.appliedCoupon.expires_at).toLocaleString()})
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
