export type Product = { id: string; name: string; price_satang: number; stock: number };
export type CartItem = { productId: string; qty: number };

export type QuoteResponse = {
  ok: boolean;
  errors: string[];
  messages: string[];
  userId: string;
  items: Array<{
    productId: string;
    name: string;
    price_satang: number;
    qty: number;
    stock: number;
    line_total_satang: number;
  }>;
  couponCode: string | null;
  appliedCoupon: null | {
    code: string;
    amount_satang: number;
    min_subtotal_satang: number;
    expires_at: string;
    per_user_limit: number | null;
  };
  pricing: {
    subtotal_satang: number;
    auto_discount_satang: number;
    subtotal_after_auto_satang: number;
    coupon_discount_satang: number;
    total_satang: number;
  };
};

export async function getProducts(): Promise<Product[]> {
  const res = await fetch("/api/products");
  const json = await res.json();
  return json.products as Product[];
}

async function postJson<T>(url: string, payload: unknown): Promise<T> {
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  const json = await res.json();
  return json as T;
}

export function quote(payload: { userId: string; items: CartItem[]; couponCode?: string }) {
  return postJson<QuoteResponse>("/api/checkout/quote", payload);
}

export function confirm(payload: { userId: string; items: CartItem[]; couponCode?: string }) {
  return postJson<QuoteResponse>("/api/checkout/confirm", payload);
}

export function formatBaht(satang: number): string {
  return (satang / 100).toFixed(2);
}
"""))

write("frontend/src/storage.ts", textwrap.dedent("""\
import type { CartItem } from "./api";

const CART_KEY = "promo-shop-cart-v2";
const SAVED_KEY = "promo-shop-saved-v2";
const USER_KEY = "promo-shop-user-v2";

export function loadCart(): CartItem[] {
  try {
    const raw = localStorage.getItem(CART_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(x => x && typeof x.productId === "string" && Number.isInteger(x.qty) && x.qty > 0);
  } catch {
    return [];
  }
}

export function saveCart(items: CartItem[]) {
  localStorage.setItem(CART_KEY, JSON.stringify(items));
}

export function loadSaved(): CartItem[] {
  try {
    const raw = localStorage.getItem(SAVED_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(x => x && typeof x.productId === "string" && Number.isInteger(x.qty) && x.qty > 0);
  } catch {
    return [];
  }
}

export function saveSaved(items: CartItem[]) {
  localStorage.setItem(SAVED_KEY, JSON.stringify(items));
}

export function loadUserId(): string {
  return localStorage.getItem(USER_KEY) || "guest";
}

export function saveUserId(userId: string) {
  localStorage.setItem(USER_KEY, userId);
}
